from typing import List

def separate_paren_groups(paren_string: str) -> List[str]:
    # Remove spaces from the input string
    paren_string = paren_string.replace(" ", "")

    # Initialize an empty list to store the extracted groups
    extracted_groups = []

    # Iterate through the input string and identify individual groups of nested parentheses
    start = 0
    count = 0
    for i, char in enumerate(paren_string):
        if char == '(':
            count += 1
        elif char == ')':
            count -= 1
            if count == 0:
                extracted_groups.append(paren_string[start:i+1])
                start = i + 1

    # Check if each identified group is balanced
    def is_balanced(group):
        stack = []
        for char in group:
            if char == '(':
                stack.append(char)
            elif char == ')':
                if not stack or stack[-1] != '(':
                    return False
                stack.pop()
        return not stack

    # Filter out unbalanced groups
    extracted_groups = [group for group in extracted_groups if is_balanced(group)]

    # Return the list of extracted groups
    return extracted_groups

